const infinity = int(1e9)

func main() {
	// Example 1: Unweighted graph for BFS
	unweightedGraph := [][]int{
		{1, 2},
		{0, 3, 4},
		{0, 5},
		{1},
		{1},
		{2},
	}

	distances, predecessors := BreadthFirstSearch(unweightedGraph, 0)
	fmt.Println("BFS Results:")
	fmt.Printf("Distances: %v\n", distances)
	fmt.Printf("Predecessors: %v\n", predecessors)
	fmt.Println()

	weightedGraph := [][]int{
		{1, 2},
		{0, 3, 4},
		{0, 5},
		{1},
		{1},
		{2},
	}
	weights := [][]int{
		{5, 10},
		{5, 3, 2},
		{10, 2},
		{3},
		{2},
		{2},
	}

	dijkstraDistances, dijkstraPredecessors := Dijkstra(weightedGraph, weights, 0)
	fmt.Println("Dijkstra Results:")
	fmt.Printf("Distances: %v\n", dijkstraDistances)
	fmt.Printf("Predecessors: %v\n", dijkstraPredecessors)
	fmt.Println()

	negativeWeightGraph := [][]int{
		{1, 2},
		{3},
		{1, 3},
		{4},
		{},
	}
	negativeWeights := [][]int{
		{6, 7},
		{5},
		{-2, 4},
		{2},
		{},
	}

	bfDistances, hasPath, bfPredecessors := BellmanFord(negativeWeightGraph, negativeWeights, 0)
	fmt.Println("Bellman-Ford Results:")
	fmt.Printf("Distances: %v\n", bfDistances)
	fmt.Printf("Has Path: %v\n", hasPath)
	fmt.Printf("Predecessors: %v\n", bfPredecessors)
}

// BreadthFirstSearch implements BFS for unweighted graphs to find shortest paths
// from a source vertex to all other vertices.
func BreadthFirstSearch(graph [][]int, source int) ([]int, []int) {
	n := len(graph)
	distances := make([]int, n)
	predecessors := make([]int, n)
	for i := range distances {
		distances[i] = infinity
		predecessors[i] = -1
	}

	distances[source] = 0
	queue := []int{source}

	for len(queue) > 0 {
		u := queue[0]
		queue = queue[1:]
		for _, v := range graph[u] {
			if distances[v] == infinity {
				distances[v] = distances[u] + 1
				predecessors[v] = u
				queue = append(queue, v)
			}
		}
	}

	return distances, predecessors
}

// item is an element in the priority queue used by Dijkstra.
type item struct {
	vertex int
	dist   int
}

type priorityQueue []item

func (pq priorityQueue) Len() int            { return len(pq) }
func (pq priorityQueue) Less(i, j int) bool  { return pq[i].dist < pq[j].dist }
func (pq priorityQueue) Swap(i, j int)       { pq[i], pq[j] = pq[j], pq[i] }
func (pq *priorityQueue) Push(x interface{}) { *pq = append(*pq, x.(item)) }
func (pq *priorityQueue) Pop() interface{} {
	old := *pq
	n := len(old)
	it := old[n-1]
	*pq = old[:n-1]
	return it
}

// Dijkstra implements Dijkstra's algorithm for weighted graphs with non-negative weights.
func Dijkstra(graph [][]int, weights [][]int, source int) ([]int, []int) {
	n := len(graph)
	distances := make([]int, n)
	predecessors := make([]int, n)
	for i := range distances {
		distances[i] = infinity
		predecessors[i] = -1
	}

	distances[source] = 0
	pq := &priorityQueue{{vertex: source, dist: 0}}
	heap.Init(pq)

	for pq.Len() > 0 {
		cur := heap.Pop(pq).(item)
		u := cur.vertex
		if cur.dist > distances[u] {
			continue
		}
		for j, v := range graph[u] {
			w := weights[u][j]
			if distances[u]+w < distances[v] {
				distances[v] = distances[u] + w
				predecessors[v] = u
				heap.Push(pq, item{vertex: v, dist: distances[v]})
			}
		}
	}

	return distances, predecessors
}

// BellmanFord implements the Bellman-Ford algorithm for weighted graphs that may contain
// negative weight edges, with detection of negative cycles.
func BellmanFord(graph [][]int, weights [][]int, source int) ([]int, []bool, []int) {
	n := len(graph)
	distances := make([]int, n)
	predecessors := make([]int, n)
	hasPath := make([]bool, n)
	for i := range distances {
		distances[i] = infinity
		predecessors[i] = -1
		hasPath[i] = false
	}

	distances[source] = 0
	hasPath[source] = true

	// Relax all edges n-1 times.
	for iter := 0; iter < n-1; iter++ {
		for u := 0; u < n; u++ {
			if distances[u] == infinity {
				continue
			}
			for j, v := range graph[u] {
				w := weights[u][j]
				if distances[u]+w < distances[v] {
					distances[v] = distances[u] + w
					predecessors[v] = u
				}
			}
		}
	}

	// hasPath is true for any vertex reachable from source.
	for i := 0; i < n; i++ {
		if distances[i] != infinity {
			hasPath[i] = true
		}
	}

	// Detect vertices affected by negative cycles. If an edge can still be
	// relaxed, the destination (and everything reachable from it) is part of
	// or downstream from a negative cycle and has no well-defined shortest path.
	affected := make([]bool, n)
	for u := 0; u < n; u++ {
		if distances[u] == infinity {
			continue
		}
		for j, v := range graph[u] {
			w := weights[u][j]
			if distances[u]+w < distances[v] {
				affected[v] = true
			}
		}
	}

	// Propagate the "affected" flag to all reachable vertices.
	queue := []int{}
	for i := 0; i < n; i++ {
		if affected[i] {
			queue = append(queue, i)
		}
	}
	for len(queue) > 0 {
		u := queue[0]
		queue = queue[1:]
		hasPath[u] = false
		for _, v := range graph[u] {
			if !affected[v] {
				affected[v] = true
				queue = append(queue, v)
			}
		}
	}

	return distances, hasPath, predecessors
}

package main

import "fmt"

type Employee struct {
	ID     int
	Name   string
	Age    int
	Salary float64
}

type Manager struct {
	Employees []Employee
}

// AddEmployee adds a new employee to the manager's list.
func (m *Manager) AddEmployee(e Employee) {
	m.Employees = append(m.Employees, e)
}

// RemoveEmployee removes an employee by ID from the manager's list.
func (m *Manager) RemoveEmployee(id int) {
	for i, e := range m.Employees {
		if e.ID == id {
			m.Employees = append(m.Employees[:i], m.Employees[i+1:]...)
			return
		}
	}
}

// GetAverageSalary calculates the average salary of all employees.
func (m *Manager) GetAverageSalary() float64 {
	if len(m.Employees) == 0 {
		return 0
	}
	var total float64
	for _, e := range m.Employees {
		total += e.Salary
	}
	return total / float64(len(m.Employees))
}

// FindEmployeeByID finds and returns an employee by their ID.
func (m *Manager) FindEmployeeByID(id int) *Employee {
	for i := range m.Employees {
		if m.Employees[i].ID == id {
			return &m.Employees[i]
		}
	}
	return nil
}

func main() {
	manager := Manager{}
	manager.AddEmployee(Employee{ID: 1, Name: "Alice", Age: 30, Salary: 70000})
	manager.AddEmployee(Employee{ID: 2, Name: "Bob", Age: 25, Salary: 65000})
	manager.RemoveEmployee(1)
	averageSalary := manager.GetAverageSalary()
	employee := manager.FindEmployeeByID(2)

	fmt.Printf("Average Salary: %f\n", averageSalary)
	if employee != nil {
		fmt.Printf("Employee found: %+v\n", *employee)
	}
}

