package generics

import "errors"

// ErrEmptyCollection is returned when an operation cannot be performed on an empty collection
var ErrEmptyCollection = errors.New("collection is empty")

//
// 1. Generic Pair
//

// Pair represents a generic pair of values of potentially different types
type Pair[T, U any] struct {
	First  T
	Second U
}

// NewPair creates a new pair with the given values
func NewPair[T, U any](first T, second U) Pair[T, U] {
	return Pair[T, U]{First: first, Second: second}
}

// Swap returns a new pair with the elements swapped
func (p Pair[T, U]) Swap() Pair[U, T] {
	return Pair[U, T]{First: p.Second, Second: p.First}
}

//
// 2. Generic Stack
//

// Stack is a generic Last-In-First-Out (LIFO) data structure
type Stack[T any] struct {
	items []T
}

// NewStack creates a new empty stack
func NewStack[T any]() *Stack[T] {
	return &Stack[T]{items: make([]T, 0)}
}

// Push adds an element to the top of the stack
func (s *Stack[T]) Push(value T) {
	s.items = append(s.items, value)
}

// Pop removes and returns the top element from the stack
// Returns an error if the stack is empty
func (s *Stack[T]) Pop() (T, error) {
	var zero T
	if len(s.items) == 0 {
		return zero, ErrEmptyCollection
	}
	idx := len(s.items) - 1
	val := s.items[idx]
	s.items = s.items[:idx]
	return val, nil
}

// Peek returns the top element without removing it
// Returns an error if the stack is empty
func (s *Stack[T]) Peek() (T, error) {
	var zero T
	if len(s.items) == 0 {
		return zero, ErrEmptyCollection
	}
	return s.items[len(s.items)-1], nil
}

// Size returns the number of elements in the stack
func (s *Stack[T]) Size() int {
	return len(s.items)
}

// IsEmpty returns true if the stack contains no elements
func (s *Stack[T]) IsEmpty() bool {
	return len(s.items) == 0
}

//
// 3. Generic Queue
//

// Queue is a generic First-In-First-Out (FIFO) data structure
type Queue[T any] struct {
	items []T
}

// NewQueue creates a new empty queue
func NewQueue[T any]() *Queue[T] {
	return &Queue[T]{items: make([]T, 0)}
}

// Enqueue adds an element to the end of the queue
func (q *Queue[T]) Enqueue(value T) {
	q.items = append(q.items, value)
}

// Dequeue removes and returns the front element from the queue
// Returns an error if the queue is empty
func (q *Queue[T]) Dequeue() (T, error) {
	var zero T
	if len(q.items) == 0 {
		return zero, ErrEmptyCollection
	}
	val := q.items[0]
	q.items = q.items[1:]
	return val, nil
}

// Front returns the front element without removing it
// Returns an error if the queue is empty
func (q *Queue[T]) Front() (T, error) {
	var zero T
	if len(q.items) == 0 {
		return zero, ErrEmptyCollection
	}
	return q.items[0], nil
}

// Size returns the number of elements in the queue
func (q *Queue[T]) Size() int {
	return len(q.items)
}

// IsEmpty returns true if the queue contains no elements
func (q *Queue[T]) IsEmpty() bool {
	return len(q.items) == 0
}

//
// 4. Generic Set
//

// Set is a generic collection of unique elements
type Set[T comparable] struct {
	items map[T]struct{}
}

// NewSet creates a new empty set
func NewSet[T comparable]() *Set[T] {
	return &Set[T]{items: make(map[T]struct{})}
}

// Add adds an element to the set if it's not already present
func (s *Set[T]) Add(value T) {
	s.items[value] = struct{}{}
}

// Remove removes an element from the set if it exists
func (s *Set[T]) Remove(value T) {
	delete(s.items, value)
}

// Contains returns true if the set contains the given element
func (s *Set[T]) Contains(value T) bool {
	_, ok := s.items[value]
	return ok
}

// Size returns the number of elements in the set
func (s *Set[T]) Size() int {
	return len(s.items)
}

// Elements returns a slice containing all elements in the set
func (s *Set[T]) Elements() []T {
	result := make([]T, 0, len(s.items))
	for k := range s.items {
		result = append(result, k)
	}
	return result
}

// Union returns a new set containing all elements from both sets
func Union[T comparable](s1, s2 *Set[T]) *Set[T] {
	result := NewSet[T]()
	for k := range s1.items {
		result.Add(k)
	}
	for k := range s2.items {
		result.Add(k)
	}
	return result
}

// Intersection returns a new set containing only elements that exist in both sets
func Intersection[T comparable](s1, s2 *Set[T]) *Set[T] {
	result := NewSet[T]()
	for k := range s1.items {
		if s2.Contains(k) {
			result.Add(k)
		}
	}
	return result
}

// Difference returns a new set with elements in s1 that are not in s2
func Difference[T comparable](s1, s2 *Set[T]) *Set[T] {
	result := NewSet[T]()
	for k := range s1.items {
		if !s2.Contains(k) {
			result.Add(k)
		}
	}
	return result
}

//
// 5. Generic Utility Functions
//

// Filter returns a new slice containing only the elements for which the predicate returns true
func Filter[T any](slice []T, predicate func(T) bool) []T {
	result := make([]T, 0)
	for _, v := range slice {
		if predicate(v) {
			result = append(result, v)
		}
	}
	return result
}

// Map applies a function to each element in a slice and returns a new slice with the results
func Map[T, U any](slice []T, mapper func(T) U) []U {
	result := make([]U, 0, len(slice))
	for _, v := range slice {
		result = append(result, mapper(v))
	}
	return result
}

// Reduce reduces a slice to a single value by applying a function to each element
func Reduce[T, U any](slice []T, initial U, reducer func(U, T) U) U {
	acc := initial
	for _, v := range slice {
		acc = reducer(acc, v)
	}
	return acc
}

// Contains returns true if the slice contains the given element
func Contains[T comparable](slice []T, element T) bool {
	for _, v := range slice {
		if v == element {
			return true
		}
	}
	return false
}

// FindIndex returns the index of the first occurrence of the given element or -1 if not found
func FindIndex[T comparable](slice []T, element T) int {
	for i, v := range slice {
		if v == element {
			return i
		}
	}
	return -1
}

// RemoveDuplicates returns a new slice with duplicate elements removed, preserving order
func RemoveDuplicates[T comparable](slice []T) []T {
	seen := make(map[T]struct{})
	result := make([]T, 0, len(slice))
	for _, v := range slice {
		if _, ok := seen[v]; !ok {
			seen[v] = struct{}{}
			result = append(result, v)
		}
	}
	return result
}

package cache

import (
	"container/list"
	"sync"
)

// Cache interface defines the contract for all cache implementations
type Cache interface {
	Get(key string) (value interface{}, found bool)
	Put(key string, value interface{})
	Delete(key string) bool
	Clear()
	Size() int
	Capacity() int
	HitRate() float64
}

// CachePolicy represents the eviction policy type
type CachePolicy int

const (
	LRU CachePolicy = iota
	LFU
	FIFO
)

//
// LRU Cache Implementation
//

type lruEntry struct {
	key   string
	value interface{}
}

type LRUCache struct {
	capacity int
	ll       *list.List
	items    map[string]*list.Element
	hits     int64
	misses   int64
}

// NewLRUCache creates a new LRU cache with the specified capacity
func NewLRUCache(capacity int) *LRUCache {
	return &LRUCache{
		capacity: capacity,
		ll:       list.New(),
		items:    make(map[string]*list.Element),
	}
}

func (c *LRUCache) Get(key string) (interface{}, bool) {
	if elem, ok := c.items[key]; ok {
		c.ll.MoveToFront(elem)
		c.hits++
		return elem.Value.(*lruEntry).value, true
	}
	c.misses++
	return nil, false
}

func (c *LRUCache) Put(key string, value interface{}) {
	if c.capacity <= 0 {
		return
	}
	if elem, ok := c.items[key]; ok {
		elem.Value.(*lruEntry).value = value
		c.ll.MoveToFront(elem)
		return
	}
	elem := c.ll.PushFront(&lruEntry{key: key, value: value})
	c.items[key] = elem

	if c.ll.Len() > c.capacity {
		c.evict()
	}
}

func (c *LRUCache) evict() {
	elem := c.ll.Back()
	if elem != nil {
		c.ll.Remove(elem)
		delete(c.items, elem.Value.(*lruEntry).key)
	}
}

func (c *LRUCache) Delete(key string) bool {
	if elem, ok := c.items[key]; ok {
		c.ll.Remove(elem)
		delete(c.items, key)
		return true
	}
	return false
}

func (c *LRUCache) Clear() {
	c.ll.Init()
	c.items = make(map[string]*list.Element)
}

func (c *LRUCache) Size() int {
	return c.ll.Len()
}

func (c *LRUCache) Capacity() int {
	return c.capacity
}

func (c *LRUCache) HitRate() float64 {
	total := c.hits + c.misses
	if total == 0 {
		return 0.0
	}
	return float64(c.hits) / float64(total)
}

//
// LFU Cache Implementation
//

type lfuEntry struct {
	key   string
	value interface{}
	freq  int
	// insertion order within the same frequency bucket is tracked by list position
}

type LFUCache struct {
	capacity int
	minFreq  int
	items    map[string]*list.Element // key -> element in freqList[freq]
	freqList map[int]*list.List       // freq -> doubly-linked list of *lfuEntry (front = newest)
	hits     int64
	misses   int64
}

// NewLFUCache creates a new LFU cache with the specified capacity
func NewLFUCache(capacity int) *LFUCache {
	return &LFUCache{
		capacity: capacity,
		items:    make(map[string]*list.Element),
		freqList: make(map[int]*list.List),
	}
}

func (c *LFUCache) touch(elem *list.Element) {
	entry := elem.Value.(*lfuEntry)
	oldFreq := entry.freq

	// remove from old freq list
	c.freqList[oldFreq].Remove(elem)
	if c.freqList[oldFreq].Len() == 0 {
		delete(c.freqList, oldFreq)
		if c.minFreq == oldFreq {
			c.minFreq++
		}
	}

	// add to new freq list
	entry.freq++
	if c.freqList[entry.freq] == nil {
		c.freqList[entry.freq] = list.New()
	}
	newElem := c.freqList[entry.freq].PushFront(entry)
	c.items[entry.key] = newElem
}

func (c *LFUCache) Get(key string) (interface{}, bool) {
	if elem, ok := c.items[key]; ok {
		value := elem.Value.(*lfuEntry).value
		c.touch(elem)
		c.hits++
		return value, true
	}
	c.misses++
	return nil, false
}

func (c *LFUCache) Put(key string, value interface{}) {
	if c.capacity <= 0 {
		return
	}
	if elem, ok := c.items[key]; ok {
		elem.Value.(*lfuEntry).value = value
		c.touch(elem)
		return
	}

	if len(c.items) >= c.capacity {
		c.evict()
	}

	entry := &lfuEntry{key: key, value: value, freq: 1}
	if c.freqList[1] == nil {
		c.freqList[1] = list.New()
	}
	elem := c.freqList[1].PushFront(entry)
	c.items[key] = elem
	c.minFreq = 1
}

func (c *LFUCache) evict() {
	l := c.freqList[c.minFreq]
	if l == nil {
		return
	}
	// evict the oldest (back) among the least frequently used
	elem := l.Back()
	if elem != nil {
		entry := elem.Value.(*lfuEntry)
		l.Remove(elem)
		if l.Len() == 0 {
			delete(c.freqList, c.minFreq)
		}
		delete(c.items, entry.key)
	}
}

func (c *LFUCache) Delete(key string) bool {
	if elem, ok := c.items[key]; ok {
		entry := elem.Value.(*lfuEntry)
		c.freqList[entry.freq].Remove(elem)
		if c.freqList[entry.freq].Len() == 0 {
			delete(c.freqList, entry.freq)
		}
		delete(c.items, key)
		return true
	}
	return false
}

func (c *LFUCache) Clear() {
	c.items = make(map[string]*list.Element)
	c.freqList = make(map[int]*list.List)
	c.minFreq = 0
}

func (c *LFUCache) Size() int {
	return len(c.items)
}

func (c *LFUCache) Capacity() int {
	return c.capacity
}

func (c *LFUCache) HitRate() float64 {
	total := c.hits + c.misses
	if total == 0 {
		return 0.0
	}
	return float64(c.hits) / float64(total)
}

//
// FIFO Cache Implementation
//

type fifoEntry struct {
	key   string
	value interface{}
}

type FIFOCache struct {
	capacity int
	ll       *list.List
	items    map[string]*list.Element
	hits     int64
	misses   int64
}

// NewFIFOCache creates a new FIFO cache with the specified capacity
func NewFIFOCache(capacity int) *FIFOCache {
	return &FIFOCache{
		capacity: capacity,
		ll:       list.New(),
		items:    make(map[string]*list.Element),
	}
}

func (c *FIFOCache) Get(key string) (interface{}, bool) {
	if elem, ok := c.items[key]; ok {
		c.hits++
		return elem.Value.(*fifoEntry).value, true
	}
	c.misses++
	return nil, false
}

func (c *FIFOCache) Put(key string, value interface{}) {
	if c.capacity <= 0 {
		return
	}
	if elem, ok := c.items[key]; ok {
		// Update value but do not change insertion order
		elem.Value.(*fifoEntry).value = value
		return
	}
	elem := c.ll.PushFront(&fifoEntry{key: key, value: value})
	c.items[key] = elem

	if c.ll.Len() > c.capacity {
		c.evict()
	}
}

func (c *FIFOCache) evict() {
	elem := c.ll.Back()
	if elem != nil {
		c.ll.Remove(elem)
		delete(c.items, elem.Value.(*fifoEntry).key)
	}
}

func (c *FIFOCache) Delete(key string) bool {
	if elem, ok := c.items[key]; ok {
		c.ll.Remove(elem)
		delete(c.items, key)
		return true
	}
	return false
}

func (c *FIFOCache) Clear() {
	c.ll.Init()
	c.items = make(map[string]*list.Element)
}

func (c *FIFOCache) Size() int {
	return c.ll.Len()
}

func (c *FIFOCache) Capacity() int {
	return c.capacity
}

func (c *FIFOCache) HitRate() float64 {
	total := c.hits + c.misses
	if total == 0 {
		return 0.0
	}
	return float64(c.hits) / float64(total)
}

//
// Thread-Safe Cache Wrapper
//

type ThreadSafeCache struct {
	cache Cache
	mu    sync.RWMutex
}

// NewThreadSafeCache wraps any cache implementation to make it thread-safe
func NewThreadSafeCache(cache Cache) *ThreadSafeCache {
	return &ThreadSafeCache{cache: cache}
}

func (c *ThreadSafeCache) Get(key string) (interface{}, bool) {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.cache.Get(key)
}

func (c *ThreadSafeCache) Put(key string, value interface{}) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.cache.Put(key, value)
}

func (c *ThreadSafeCache) Delete(key string) bool {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.cache.Delete(key)
}

func (c *ThreadSafeCache) Clear() {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.cache.Clear()
}

func (c *ThreadSafeCache) Size() int {
	c.mu.RLock()
	defer c.mu.RUnlock()
	return c.cache.Size()
}

func (c *ThreadSafeCache) Capacity() int {
	c.mu.RLock()
	defer c.mu.RUnlock()
	return c.cache.Capacity()
}

func (c *ThreadSafeCache) HitRate() float64 {
	c.mu.RLock()
	defer c.mu.RUnlock()
	return c.cache.HitRate()
}

//
// Cache Factory Functions
//

// NewCache creates a cache with the specified policy and capacity
func NewCache(policy CachePolicy, capacity int) Cache {
	switch policy {
	case LRU:
		return NewLRUCache(capacity)
	case LFU:
		return NewLFUCache(capacity)
	case FIFO:
		return NewFIFOCache(capacity)
	default:
		return NewLRUCache(capacity)
	}
}

// NewThreadSafeCacheWithPolicy creates a thread-safe cache with the specified policy
func NewThreadSafeCacheWithPolicy(policy CachePolicy, capacity int) Cache {
	return NewThreadSafeCache(NewCache(policy, capacity))
}

package main

import "sync"

// bfs computes the breadth-first search order starting from the given node.
func bfs(graph map[int][]int, start int) []int {
	queue := []int{start}
	visited := map[int]bool{start: true}
	var order []int

	for len(queue) > 0 {
		u := queue[0]
		queue = queue[1:]
		order = append(order, u)

		for _, v := range graph[u] {
			if !visited[v] {
				visited[v] = true
				queue = append(queue, v)
			}
		}
	}

	return order
}

// ConcurrentBFSQueries concurrently processes BFS queries on the provided graph.
// - graph: adjacency list, e.g., graph[u] = []int{v1, v2, ...}
// - queries: a list of starting nodes for BFS.
// - numWorkers: how many goroutines can process BFS queries simultaneously.
//
// Return a map from the query (starting node) to the BFS order as a slice of nodes.
func ConcurrentBFSQueries(graph map[int][]int, queries []int, numWorkers int) map[int][]int {
	results := make(map[int][]int)

	if numWorkers <= 0 || len(queries) == 0 {
		return results
	}

	jobs := make(chan int)

	var mu sync.Mutex
	var wg sync.WaitGroup

	worker := func() {
		defer wg.Done()
		for start := range jobs {
			order := bfs(graph, start)
			mu.Lock()
			results[start] = order
			mu.Unlock()
		}
	}

	for i := 0; i < numWorkers; i++ {
		wg.Add(1)
		go worker()
	}

	for _, q := range queries {
		jobs <- q
	}
	close(jobs)

	wg.Wait()

	return results
}

