// Package challenge8 contains the solution for Challenge 8: Chat Server with Channels.
package challenge8

import (
	"errors"
	"fmt"
	"sync"
)

// Client represents a connected chat client
type Client struct {
	username     string
	messages     chan string
	mu           sync.Mutex
	disconnected bool
	closeOnce    sync.Once
}

// Send sends a message to the client.
// It is thread-safe and performs a non-blocking send so that a slow or
// full client does not block the server.
func (c *Client) Send(message string) {
	c.mu.Lock()
	defer c.mu.Unlock()

	if c.disconnected {
		return
	}

	select {
	case c.messages <- message:
	default:
		// Drop the message if the buffer is full to avoid blocking.
	}
}

// Receive returns the next message for the client (blocking).
// It returns an empty string when the client's channel is closed.
func (c *Client) Receive() string {
	msg, ok := <-c.messages
	if !ok {
		return ""
	}
	return msg
}

// close marks the client as disconnected and closes its message channel.
func (c *Client) close() {
	c.closeOnce.Do(func() {
		c.mu.Lock()
		c.disconnected = true
		close(c.messages)
		c.mu.Unlock()
	})
}

// isDisconnected reports whether the client has been disconnected.
func (c *Client) isDisconnected() bool {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.disconnected
}

// ChatServer manages client connections and message routing
type ChatServer struct {
	mu      sync.RWMutex
	clients map[string]*Client
}

// NewChatServer creates a new chat server instance
func NewChatServer() *ChatServer {
	return &ChatServer{
		clients: make(map[string]*Client),
	}
}

// Connect adds a new client to the chat server
func (s *ChatServer) Connect(username string) (*Client, error) {
	if username == "" {
		return nil, errors.New("username cannot be empty")
	}

	s.mu.Lock()
	defer s.mu.Unlock()

	if _, exists := s.clients[username]; exists {
		return nil, ErrUsernameAlreadyTaken
	}

	client := &Client{
		username: username,
		messages: make(chan string, 100),
	}
	s.clients[username] = client

	return client, nil
}

// Disconnect removes a client from the chat server
func (s *ChatServer) Disconnect(client *Client) {
	if client == nil {
		return
	}

	s.mu.Lock()
	if existing, ok := s.clients[client.username]; ok && existing == client {
		delete(s.clients, client.username)
	}
	s.mu.Unlock()

	client.close()
}

// Broadcast sends a message to all connected clients
func (s *ChatServer) Broadcast(sender *Client, message string) {
	var formatted string
	if sender != nil {
		formatted = fmt.Sprintf("%s: %s", sender.username, message)
	} else {
		formatted = message
	}

	s.mu.RLock()
	recipients := make([]*Client, 0, len(s.clients))
	for _, c := range s.clients {
		recipients = append(recipients, c)
	}
	s.mu.RUnlock()

	for _, c := range recipients {
		c.Send(formatted)
	}
}

// PrivateMessage sends a message to a specific client
func (s *ChatServer) PrivateMessage(sender *Client, recipient string, message string) error {
	if sender == nil {
		return ErrClientDisconnected
	}

	if sender.isDisconnected() {
		return ErrClientDisconnected
	}

	s.mu.RLock()
	// Ensure the sender is still a registered client.
	if existing, ok := s.clients[sender.username]; !ok || existing != sender {
		s.mu.RUnlock()
		return ErrClientDisconnected
	}

	target, ok := s.clients[recipient]
	s.mu.RUnlock()

	if !ok {
		return ErrRecipientNotFound
	}

	formatted := fmt.Sprintf("[private] %s: %s", sender.username, message)
	target.Send(formatted)

	return nil
}

// Common errors that can be returned by the Chat Server
var (
	ErrUsernameAlreadyTaken = errors.New("username already taken")
	ErrRecipientNotFound    = errors.New("recipient not found")
	ErrClientDisconnected   = errors.New("client disconnected")
)

