// Package challenge12 contains the solution for Challenge 12.
package challenge12

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
)

// Reader defines an interface for data sources
type Reader interface {
	Read(ctx context.Context) ([]byte, error)
}

// Validator defines an interface for data validation
type Validator interface {
	Validate(data []byte) error
}

// Transformer defines an interface for data transformation
type Transformer interface {
	Transform(data []byte) ([]byte, error)
}

// Writer defines an interface for data destinations
type Writer interface {
	Write(ctx context.Context, data []byte) error
}

// ValidationError represents an error during data validation
type ValidationError struct {
	Field   string
	Message string
	Err     error
}

// Error returns a string representation of the ValidationError
func (e *ValidationError) Error() string {
	if e.Err != nil {
		return fmt.Sprintf("validation error on field %q: %s: %v", e.Field, e.Message, e.Err)
	}
	return fmt.Sprintf("validation error on field %q: %s", e.Field, e.Message)
}

// Unwrap returns the underlying error
func (e *ValidationError) Unwrap() error {
	return e.Err
}

// TransformError represents an error during data transformation
type TransformError struct {
	Stage string
	Err   error
}

// Error returns a string representation of the TransformError
func (e *TransformError) Error() string {
	if e.Err != nil {
		return fmt.Sprintf("transform error at stage %q: %v", e.Stage, e.Err)
	}
	return fmt.Sprintf("transform error at stage %q", e.Stage)
}

// Unwrap returns the underlying error
func (e *TransformError) Unwrap() error {
	return e.Err
}

// PipelineError represents an error in the processing pipeline
type PipelineError struct {
	Stage string
	Err   error
}

// Error returns a string representation of the PipelineError
func (e *PipelineError) Error() string {
	if e.Err != nil {
		return fmt.Sprintf("pipeline error at stage %q: %v", e.Stage, e.Err)
	}
	return fmt.Sprintf("pipeline error at stage %q", e.Stage)
}

// Unwrap returns the underlying error
func (e *PipelineError) Unwrap() error {
	return e.Err
}

// Sentinel errors for common error conditions
var (
	ErrInvalidFormat    = errors.New("invalid data format")
	ErrMissingField     = errors.New("required field missing")
	ErrProcessingFailed = errors.New("processing failed")
	ErrDestinationFull  = errors.New("destination is full")
)

// Pipeline orchestrates the data processing flow
type Pipeline struct {
	Reader       Reader
	Validators   []Validator
	Transformers []Transformer
	Writer       Writer
}

// NewPipeline creates a new processing pipeline with specified components
func NewPipeline(r Reader, v []Validator, t []Transformer, w Writer) *Pipeline {
	if r == nil || w == nil {
		return nil
	}
	return &Pipeline{
		Reader:       r,
		Validators:   v,
		Transformers: t,
		Writer:       w,
	}
}

// Process runs the complete pipeline
func (p *Pipeline) Process(ctx context.Context) error {
	// Read
	data, err := p.Reader.Read(ctx)
	if err != nil {
		return &PipelineError{Stage: "read", Err: err}
	}

	// Validate
	for _, v := range p.Validators {
		if err := v.Validate(data); err != nil {
			return &PipelineError{Stage: "validation", Err: err}
		}
	}

	// Transform
	for _, t := range p.Transformers {
		data, err = t.Transform(data)
		if err != nil {
			return &PipelineError{Stage: "transformation", Err: err}
		}
	}

	// Write
	if err := p.Writer.Write(ctx, data); err != nil {
		return &PipelineError{Stage: "write", Err: err}
	}

	return nil
}

// handleErrors consolidates errors from concurrent operations
func (p *Pipeline) handleErrors(ctx context.Context, errs <-chan error) error {
	for {
		select {
		case <-ctx.Done():
			return ctx.Err()
		case err, ok := <-errs:
			if !ok {
				return nil
			}
			if err != nil {
				return &PipelineError{Stage: "concurrent", Err: err}
			}
		}
	}
}

// FileReader implements the Reader interface for file sources
type FileReader struct {
	Filename string
}

// NewFileReader creates a new file reader
func NewFileReader(filename string) *FileReader {
	return &FileReader{Filename: filename}
}

// Read reads data from a file
func (fr *FileReader) Read(ctx context.Context) ([]byte, error) {
	select {
	case <-ctx.Done():
		return nil, ctx.Err()
	default:
	}

	data, err := os.ReadFile(fr.Filename)
	if err != nil {
		return nil, &PipelineError{Stage: "read", Err: err}
	}
	return data, nil
}

// JSONValidator implements the Validator interface for JSON validation
type JSONValidator struct{}

// NewJSONValidator creates a new JSON validator
func NewJSONValidator() *JSONValidator {
	return &JSONValidator{}
}

// Validate validates JSON data
func (jv *JSONValidator) Validate(data []byte) error {
	if !json.Valid(data) {
		return &ValidationError{
			Field:   "json",
			Message: "data is not valid JSON",
			Err:     ErrInvalidFormat,
		}
	}
	return nil
}

// SchemaValidator implements the Validator interface for schema validation
type SchemaValidator struct {
	Schema []byte
}

// NewSchemaValidator creates a new schema validator
func NewSchemaValidator(schema []byte) *SchemaValidator {
	return &SchemaValidator{Schema: schema}
}

// Validate validates data against a schema
func (sv *SchemaValidator) Validate(data []byte) error {
	var schema map[string]interface{}
	if err := json.Unmarshal(sv.Schema, &schema); err != nil {
		return &ValidationError{
			Field:   "schema",
			Message: "invalid schema definition",
			Err:     errors.Join(ErrInvalidFormat, err),
		}
	}

	var parsed map[string]interface{}
	if err := json.Unmarshal(data, &parsed); err != nil {
		return &ValidationError{
			Field:   "data",
			Message: "data is not valid JSON object",
			Err:     errors.Join(ErrInvalidFormat, err),
		}
	}

	for field := range schema {
		if _, ok := parsed[field]; !ok {
			return &ValidationError{
				Field:   field,
				Message: "required field is missing",
				Err:     ErrMissingField,
			}
		}
	}
	return nil
}

// FieldTransformer implements the Transformer interface for field transformations
type FieldTransformer struct {
	FieldName     string
	TransformFunc func(string) string
}

// NewFieldTransformer creates a new field transformer
func NewFieldTransformer(fieldName string, transformFunc func(string) string) *FieldTransformer {
	return &FieldTransformer{
		FieldName:     fieldName,
		TransformFunc: transformFunc,
	}
}

// Transform transforms a specific field in the data
func (ft *FieldTransformer) Transform(data []byte) ([]byte, error) {
	var parsed map[string]interface{}
	if err := json.Unmarshal(data, &parsed); err != nil {
		return nil, &TransformError{
			Stage: "field:" + ft.FieldName,
			Err:   errors.Join(ErrInvalidFormat, err),
		}
	}

	if val, ok := parsed[ft.FieldName]; ok {
		if str, ok := val.(string); ok {
			parsed[ft.FieldName] = ft.TransformFunc(str)
		}
	}

	out, err := json.Marshal(parsed)
	if err != nil {
		return nil, &TransformError{
			Stage: "field:" + ft.FieldName,
			Err:   err,
		}
	}
	return out, nil
}

// FileWriter implements the Writer interface for file destinations
type FileWriter struct {
	Filename string
}

// NewFileWriter creates a new file writer
func NewFileWriter(filename string) *FileWriter {
	return &FileWriter{Filename: filename}
}

// Write writes data to a file
func (fw *FileWriter) Write(ctx context.Context, data []byte) error {
	select {
	case <-ctx.Done():
		return ctx.Err()
	default:
	}

	if err := os.WriteFile(fw.Filename, data, 0644); err != nil {
		return &PipelineError{Stage: "write", Err: err}
	}
	return nil
}

package main

import (
	"context"
	"fmt"
	"time"
)

// ContextManager defines a simplified interface for basic context operations
type ContextManager interface {
	// Create a cancellable context from a parent context
	CreateCancellableContext(parent context.Context) (context.Context, context.CancelFunc)

	// Create a context with timeout
	CreateTimeoutContext(parent context.Context, timeout time.Duration) (context.Context, context.CancelFunc)

	// Add a value to context
	AddValue(parent context.Context, key, value interface{}) context.Context

	// Get a value from context
	GetValue(ctx context.Context, key interface{}) (interface{}, bool)

	// Execute a task with context cancellation support
	ExecuteWithContext(ctx context.Context, task func() error) error

	// Wait for context cancellation or completion
	WaitForCompletion(ctx context.Context, duration time.Duration) error
}

// Simple context manager implementation
type simpleContextManager struct{}

// NewContextManager creates a new context manager
func NewContextManager() ContextManager {
	return &simpleContextManager{}
}

// CreateCancellableContext creates a cancellable context
func (cm *simpleContextManager) CreateCancellableContext(parent context.Context) (context.Context, context.CancelFunc) {
	return context.WithCancel(parent)
}

// CreateTimeoutContext creates a context with timeout
func (cm *simpleContextManager) CreateTimeoutContext(parent context.Context, timeout time.Duration) (context.Context, context.CancelFunc) {
	return context.WithTimeout(parent, timeout)
}

// AddValue adds a key-value pair to the context
func (cm *simpleContextManager) AddValue(parent context.Context, key, value interface{}) context.Context {
	return context.WithValue(parent, key, value)
}

// GetValue retrieves a value from the context
func (cm *simpleContextManager) GetValue(ctx context.Context, key interface{}) (interface{}, bool) {
	value := ctx.Value(key)
	if value == nil {
		return nil, false
	}
	return value, true
}

// ExecuteWithContext executes a task that can be cancelled via context
func (cm *simpleContextManager) ExecuteWithContext(ctx context.Context, task func() error) error {
	done := make(chan error, 1)

	go func() {
		done <- task()
	}()

	select {
	case <-ctx.Done():
		return ctx.Err()
	case err := <-done:
		return err
	}
}

// WaitForCompletion waits for a duration or until context is cancelled
func (cm *simpleContextManager) WaitForCompletion(ctx context.Context, duration time.Duration) error {
	timer := time.NewTimer(duration)
	defer timer.Stop()

	select {
	case <-ctx.Done():
		return ctx.Err()
	case <-timer.C:
		return nil
	}
}

// Helper function - simulate work that can be cancelled
func SimulateWork(ctx context.Context, workDuration time.Duration, description string) error {
	fmt.Printf("Starting work: %s\n", description)

	timer := time.NewTimer(workDuration)
	defer timer.Stop()

	select {
	case <-ctx.Done():
		fmt.Printf("Work cancelled: %s\n", description)
		return ctx.Err()
	case <-timer.C:
		fmt.Printf("Work completed: %s\n", description)
		return nil
	}
}

// Helper function - process multiple items with context
func ProcessItems(ctx context.Context, items []string) ([]string, error) {
	results := make([]string, 0, len(items))

	for _, item := range items {
		// Check for cancellation before processing each item
		select {
		case <-ctx.Done():
			return results, ctx.Err()
		default:
		}

		// Simulate per-item processing work that respects cancellation
		select {
		case <-ctx.Done():
			return results, ctx.Err()
		case <-time.After(30 * time.Millisecond):
		}

		results = append(results, "processed_"+item)
	}

	return results, nil
}

// Example usage
func main() {
	fmt.Println("Context Management Challenge")
	fmt.Println("Implement the context manager methods!")

	// Example of how the context manager should work:
	cm := NewContextManager()

	// Create a cancellable context
	ctx, cancel := cm.CreateCancellableContext(context.Background())
	defer cancel()

	// Add some values
	ctx = cm.AddValue(ctx, "user", "alice")
	ctx = cm.AddValue(ctx, "requestID", "12345")

	// Use the context
	fmt.Println("Context created with values!")
}

